defmodule Sample do
      # Unlike a whole-string predicate, this parser returns the remaining suffix.
      def digits(text), do: walk(text, "")
      defp walk(<<c, rest::binary>>, acc) when c >= ?0 and c <= ?9, do: walk(rest, acc <> <<c>>)
      defp walk(rest, acc), do: {acc, rest}
    end

